// These are authored investigations within the existing stops, not extra encounters.
missions.find(mission => mission.id === 'c05-02').steps.push(
  activity('subnet', 'Decide which delivery stays local', 'network', 'Use the desk’s /24 prefix to decide which destination needs the gateway.',
    T('A network prefix tells a device which addresses are on its local IP network.', 'Compare each address with 10.24.5.12/24.', 'For these IPv4 /24 examples, the first three numbered parts are the network prefix. /24 means 24 prefix bits and corresponds to subnet mask 255.255.255.0. Other prefix lengths need their own calculation; this shortcut is not universal.', 'Explain why one destination is reached locally while another needs a route through the gateway.'),
    choose('Local subnet delivery desk', 'Inspect the desk prefix and two destinations.', [
      { id: 'desk', label: 'Desk network settings', detail: 'Address 10.24.5.12/24; mask 255.255.255.0; local network 10.24.5.0/24; gateway 10.24.5.1.' },
      { id: 'destinations', label: 'Two delivery labels', detail: 'Cabin A: 10.24.5.20. Clinic B: 10.24.6.20. These hosts use the supplied /24 network plan.' },
    ], ['desk', 'destinations'], [
      { id: 'local', label: 'Cabin A is on this local subnet; Clinic B needs routing through the gateway.', correct: true, feedback: 'The /24 network prefix matches 10.24.5 for Cabin A and differs for Clinic B.' },
      { id: 'both', label: 'Both are on the local subnet because both begin with 10.', correct: false, feedback: 'Private-range membership does not mean the addresses share this /24 subnet.' },
      { id: 'neither', label: 'Both need the gateway because neither equals the desk’s full address.', correct: false, feedback: 'Local hosts have different device addresses within the same network prefix.' },
    ]), { inspect: ['desk', 'destinations'], choice: 'local' },
    ['Which part of the address does this exact /24 plan call the network?', 'Sharing the broad private range is not the same as sharing a subnet.', 'Compare the first three numbered parts for this /24 example.', '10.24.5.20 matches the local /24; 10.24.6.20 needs the gateway.'],
    F('BRAMBLE', 'The cabin letter stays in the village; the clinic letter goes through the gate. That finally makes the little slash useful.', 'The prefix gives the gateway decision a reason instead of making it a memorised route.', 'CIDR prefix and subnet-mask intuition', 'Interpret a workstation’s subnet and identify whether a destination is local.')),
);

missions.find(mission => mission.id === 'c05-03').steps.push(
  activity('neighbour', 'Find the relay’s local delivery label', 'network', 'Inspect the neighbour record that maps the relay’s known IPv4 address to its local MAC address.',
    T('On an IPv4 LAN, ARP resolves a local IP address to a link-layer MAC address.', 'Inspect the relevant neighbour-table entry.', 'ARP is for local link delivery, not Internet-wide name lookup. The gateway’s MAC is used for delivery to a remote network; a MAC address does not authenticate a person. IPv6 uses Neighbor Discovery rather than ARP.', 'Check whether a workstation knows the local next-hop delivery address.'),
    inspect('Local neighbour table', 'Known destination relay.valley.test resolves to 10.24.5.20. Open its matching local entry.', [
      { id: 'relay', label: '10.24.5.20 → 02:24:05:00:00:20', detail: 'Reachable neighbour entry for the local relay interface. This is the matching local IPv4-to-MAC mapping, not a proof of device trust.' },
      { id: 'gateway', label: '10.24.5.1 → 02:24:05:00:00:01', detail: 'Gateway interface mapping, useful when the IP destination is outside the local subnet.' },
      { id: 'dns', label: 'DNS record relay.valley.test → 10.24.5.20', detail: 'This record translates a hostname to an IP address; it does not provide the local MAC mapping.' },
    ], ['relay']), { inspect: ['relay'] },
    ['You already know the relay’s IP; which local delivery label is still needed?', 'Differentiate a DNS name lookup from an ARP neighbour mapping.', 'Look for the entry whose IP is exactly 10.24.5.20.', 'Open 10.24.5.20 → 02:24:05:00:00:20.'],
    F('TESSA', 'The name led to an IP; the local neighbour table gives the next delivery label. Different questions, different records.', 'The mapping explains how a local frame reaches the known IP destination.', 'ARP and local next-hop resolution', 'Inspect neighbour information when a local IP connection fails despite apparently correct addressing.')),
);

missions.find(mission => mission.id === 'c05-09').steps.push(
  activity('remote', 'Give the field ranger a safe route home', 'network', 'Choose the approved remote-access route without treating a familiar Wi-Fi name or VPN as universal trust.',
    T('Wireless access and a VPN protect different parts of a connection.', 'Compare the hotspot claims with the established remote-access policy.', 'A Wi-Fi name can be copied. Use the approved secured network and verify its identity through the known process. A VPN creates a protected tunnel to its configured endpoint; it does not make unrelated websites honest or remove device and account checks.', 'Connect a remote worker through an authorised network and verified organisation VPN.'),
    choose('Field ranger connection board', 'Inspect the available network claims and approved access policy.', [
      { id: 'networks', label: 'Available network labels', detail: '“Ranger-Free” is open and has no verified owner. “Clinic-Staff” uses the approved managed WPA2/WPA3 configuration and has been confirmed by the clinic through the known support route. An identical SSID alone would not prove that identity.' },
      { id: 'policy', label: 'Established remote-access policy', detail: 'Managed ranger device; approved Clinic-Staff network; known organisation VPN profile with verified endpoint; normal account authentication and MFA. Continue verifying actual service destinations inside the tunnel.' },
    ], ['networks', 'policy'], [
      { id: 'ssid', label: 'Use Ranger-Free because the word Ranger proves ownership.', correct: false, feedback: 'An SSID is a label that someone else can copy.' },
      { id: 'vpn', label: 'Use the verified approved network and known VPN profile, retaining normal device, account and destination checks.', correct: true, feedback: 'Each part of the route is checked for its actual role.' },
      { id: 'tunnel', label: 'Use any network and ignore all destination warnings once any VPN says connected.', correct: false, feedback: 'A tunnel to an unverified endpoint or deceptive site does not supply overall trust.' },
    ]), { inspect: ['networks', 'policy'], choice: 'vpn' },
    ['Which network owner and tunnel endpoint have actually been verified?', 'A familiar name is weaker than the established configuration and contact check.', 'The policy names Clinic-Staff and the known organisation VPN profile.', 'Choose the verified approved Wi-Fi and known VPN while keeping device, account and destination checks.'],
    F('PATCH', 'A tunnel is a useful protected road, not a machine that turns every destination into a friend.', 'The route protects remote access without erasing the trust decisions at either endpoint.', 'Wi-Fi and VPN trust boundaries', 'Use approved remote-access profiles and keep normal security checks in place.')),
);

// Explicit fading within lessons: introduced tools remain explained; recalled tools
// and applications ask for an outcome before Patch supplies optional syntax.
const recallSteps = {
  'c05-01': { route: 'practice' }, 'c05-02': { labels: 'practice' }, 'c05-03': { jobs: 'practice' },
  'c05-04': { limits: 'prove' }, 'c05-05': { interpret: 'practice' }, 'c05-06': { fault: 'practice' },
  'c05-07': { risk: 'practice' }, 'c05-08': { binding: 'practice' }, 'c05-09': { repair: 'practice' },
  'c06-01': { control: 'practice' }, 'c06-02': { discover: 'practice', read: 'practice', respond: 'prove' },
  'c06-04': { triage: 'practice' }, 'c06-05': { protect: 'practice' }, 'c06-06': { response: 'practice' },
  'c06-07': { next: 'practice' }, 'c07-01': { exchange: 'practice' }, 'c07-02': { limits: 'prove' },
  'c07-03': { respond: 'practice' }, 'c07-04': { purpose: 'practice' },
  'c07-05': { reference: 'practice', verdict: 'prove' }, 'c07-06': { leak: 'practice' },
  'c07-07': { session: 'practice' }, 'c08-01': { review: 'practice' },
  'c08-03': { recent: 'practice', interpret: 'prove' }, 'c08-04': { join: 'practice' },
  'c08-05': { tune: 'practice' }, 'c08-06': { before: 'practice', copy: 'practice', after: 'prove' },
  'c08-07': { note: 'prove' }, 'c08-08': { handover: 'practice' },
};
for (const [missionId, steps] of Object.entries(recallSteps)) {
  const mission = missions.find(item => item.id === missionId);
  for (const [stepId, phase] of Object.entries(steps)) mission.steps.find(step => step.id === stepId).phase = phase;
}
